from decimal import Decimal, InvalidOperation
from typing import Any


def _order_id(row: dict) -> str:
    """Return the ORD_ID using legacy missing-key-as-empty-string behavior."""
    return str(row.get("ORD_ID", ""))


def _line_no_key(row: dict) -> tuple[int, Any]:
    """Return a stable numeric sort key for LINE_NO.

    Valid numeric values sort numerically. Missing or otherwise non-numeric
    values sort after numeric values while remaining deterministic.
    """
    value = row.get("LINE_NO", "")
    try:
        return (0, Decimal(str(value)))
    except (InvalidOperation, ValueError):
        return (1, str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted ORD_LINE rows and assign contiguous line numbers."""
    surviving = [
        row
        for row in lines
        if row.get("DEL_FLG", "") != "Y"
    ]

    grouped: dict[str, list[dict]] = {}
    for row in surviving:
        grouped.setdefault(_order_id(row), []).append(row)

    result: list[dict] = []
    for ord_id in sorted(grouped):
        ordered_lines = sorted(grouped[ord_id], key=_line_no_key)
        for new_line_no, row in enumerate(ordered_lines, start=1):
            new_row = dict(row)
            new_row["LINE_NO"] = new_line_no
            result.append(new_row)

    return result
